INSERT INTO public.knowledge_base (content, metadata, embedding, user_id) VALUES ('„Art. 22. Ustawa wchodzi w życie z dniem 1 lipca 2024 r., z wyjątkiem: 
1) 
art. 6 pkt 1, który wchodzi w życie z dniem 1 września 2024 r.; 
2) 
art. 1 pkt 25 w zakresie art. 75b ust. 5 i art. 75u ust. 10, który wchodzi w życie z dniem 1 lipca 2025 r.”; 
  
Dziennik Ustaw 
– 2 – 
Poz. 633 
 
 
3) 
art. 164 ustawy z dnia 6 listopada 2024 r. o opodatkowaniu wyrównawczym jednostek składowych grup międzynaro-
dowych i krajowych (Dz. U. poz. 1685), który stanowi: 
„Art. 164. Ustawa wchodzi w życie z dniem 1 stycznia 2025 r., z wyjątkiem art. 140 pkt 4 w zakresie art. 14zq 
§ 5 oraz art. 145 pkt 1–3, 5 i 6, które wchodzą w życie z dniem następującym po dniu ogłoszenia.”; 
4) 
art. 10 ustawy z dnia 8 listopada 2024 r. o zmianie ustawy o podatku od towarów i usług oraz niektórych innych ustaw 
(Dz. U. poz. 1721), który stanowi: 
„Art. 10. Ustawa wchodzi w życie z dniem 1 stycznia 2025 r., z wyjątkiem art. 8, który wchodzi w życie z dniem 
następującym po dniu ogłoszenia.”; 
5) 
art. 33 ustawy z dnia 24 stycznia 2025 r. o zmianie ustawy – Prawo lotnicze oraz niektórych innych ustaw (Dz. U. 
poz. 179), który stanowi: 
„Art. 33. Ustawa wchodzi w życie po upływie 14 dni od dnia ogłoszenia, z wyjątkiem: 
1) 
art. 1 pkt 3 lit. c, art. 7 i art. 20, które wchodzą w życie z dniem następującym po dniu ogłoszenia; 
2) 
art. 1 pkt 25 i 26, które wchodzą w życie po upływie 9 miesięcy od dnia ogłoszenia.”; 
